        FastReader r = new FastReader();
        int n = r.nextInt(), q = r.nextInt(), total = n + q;
        long[] values = new long[total];
        int[] following = new int[total];
        boolean[] removed = new boolean[total];
        int size = 0;
        HashMap<Long, int[]> ends = new HashMap<>();  // value -> {head, tail} of its index chain
        for (int t = 0; t < total; t++) {
            long v = r.nextLong();
            if (v > 0) {
                int index = size++;
                int[] e = ends.get(v);
                if (e != null && e[1] >= 0) {
                    following[e[1]] = index;
                    e[1] = index;
                } else if (e != null) {
                    e[0] = index;
                    e[1] = index;
                } else {
                    ends.put(v, new int[] {index, index});
                }
                values[index] = v;
                following[index] = -1;
            } else {
                int[] e = ends.get(-v);
                int index = e[0];
                e[0] = following[index];
                removed[index] = true;
                if (e[0] < 0) e[1] = -1;
            }
        }
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = 0; i < size; i++) if (!removed[i]) { count++; sb.append(' ').append(values[i]); }
        System.out.println(count + sb.toString());
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	n, q := readInt(), readInt()
	values := make([]int, 0, n+q)
	following := make([]int, 0, n+q)
	removed := make([]bool, 0, n+q)
	head, tail := map[int]int{}, map[int]int{} // index chain of each value
	for t := 0; t < n+q; t++ {
		v := readInt()
		if v > 0 {
			index := len(values)
			if previous, ok := tail[v]; ok && previous >= 0 {
				following[previous] = index
			} else {
				head[v] = index
			}
			tail[v] = index
			values = append(values, v)
			removed = append(removed, false)
			following = append(following, -1)
		} else {
			value := -v
			index := head[value]
			head[value] = following[index]
			removed[index] = true
			if head[value] < 0 {
				tail[value] = -1
			}
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var answer []int
	for i, v := range values {
		if !removed[i] {
			answer = append(answer, v)
		}
	}
	w.WriteString(strconv.Itoa(len(answer)))
	for _, v := range answer {
		w.WriteByte(' ')
		w.WriteString(strconv.Itoa(v))
	}
	w.WriteByte('\n')
}

